package com.killteamtimer.rules

import android.content.Context
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.File
import java.net.HttpURLConnection
import java.net.URL

/**
 * Names and situation tags of every team's rules, generated by tools/rules/build_rules.py from the
 * official Kill Team downloads. Holds no rules text.
 */
@Serializable
data class RulesData(
    val source: String,
    /** UTC build time; only changes when the contents do. Newer wins between bundled and downloaded. */
    val generated: String = "",
    /** Tag id -> label, in display order. */
    val tags: Map<String, String>,
    val universal: List<RuleItem>,
    val teams: List<Team>,
) {
    fun team(id: String?): Team? = teams.firstOrNull { it.id == id }

    companion object {
        /** Rebuilt weekly by .github/workflows/rules.yml; the app picks it up on next launch. */
        private const val UPDATE_URL =
            "https://raw.githubusercontent.com/Mandrews277/KillTeamTimer/master/app/src/main/assets/rules.json"
        private const val DOWNLOADED = "rules.json"

        private val json = Json { ignoreUnknownKeys = true }

        private var current by mutableStateOf<RulesData?>(null)

        /** The newest of the bundled and last downloaded rules. Recomposes when [refresh] finds newer. */
        fun load(context: Context): RulesData = current ?: synchronized(this) {
            current ?: run {
                val bundled = context.assets.open("rules.json").bufferedReader().use { parse(it.readText()) }
                val downloaded = runCatching { parse(File(context.filesDir, DOWNLOADED).readText()) }.getOrNull()
                listOfNotNull(bundled, downloaded).maxBy { it.generated }.also { current = it }
            }
        }

        /** Fetches the latest rules; keeps what we have on any failure (offline, bad file). */
        suspend fun refresh(context: Context) = withContext(Dispatchers.IO) {
            val have = load(context)
            val text = runCatching {
                (URL(UPDATE_URL).openConnection() as HttpURLConnection).run {
                    connectTimeout = 10_000
                    readTimeout = 20_000
                    try { if (responseCode == 200) inputStream.bufferedReader().use { it.readText() } else null }
                    finally { disconnect() }
                }
            }.getOrNull() ?: return@withContext
            val fresh = runCatching { parse(text) }.getOrNull() ?: return@withContext
            if (fresh.generated > have.generated && fresh.teams.isNotEmpty()) {
                File(context.filesDir, DOWNLOADED).writeText(text)
                current = fresh
            }
        }

        private fun parse(text: String) = json.decodeFromString<RulesData>(text)
    }
}

@Serializable
data class Team(val id: String, val name: String, val updated: String? = null, val items: List<RuleItem>)

@Serializable
data class RuleItem(
    val id: String,
    val kind: Kind,
    /** Card name, or the operative / faction rule that owns [sub]. */
    val heading: String,
    /** Ability, action or part name within [heading], if any. */
    val sub: String? = null,
    val tags: List<String>,
)

@Serializable
enum class Kind(val label: String) {
    FACTION_RULE("Faction rules"),
    STRATEGY_PLOY("Strategy ploys"),
    FIREFIGHT_PLOY("Firefight ploys"),
    OPERATIVE("Operatives"),
    EQUIPMENT("Equipment"),
}
